using System.Diagnostics;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;
using ProcessLens.Core;
using ProcessLens.Windows;

namespace ProcessLens.App;

public partial class NetworkCaptureView : UserControl
{
    private readonly IPacketCaptureClient _client;
    private CaptureTools? _tools;
    private string? _selectedDumpcap, _lastFile;
    private string? _capturedFile;
    private string _captureDetail = "";
    private PacketEvidence? _evidence;
    private CancellationTokenSource? _operation;
    private bool _active, _busy, _monitorVerified, _fileReady;
    private int _generation;
    public NetworkCaptureView() : this(new WiresharkTools()) { }
    internal NetworkCaptureView(IPacketCaptureClient client) { _client = client; InitializeComponent(); UpdateButtons(); }
    public void SetActive(bool active)
    {
        _active = active;
        if (!active)
        {
            _generation++; _operation?.Cancel(); _monitorVerified = false; _evidence = null;
            CaptureObservationsTable.ItemsSource = null;
            CaptureSummaryText.Text = "Campione rilasciato. Le operazioni in corso vengono interrotte.";
            CaptureStatusText.Text = "Vista sospesa. Nessuna cattura automatica alla riapertura.";
        }
        UpdateButtons();
    }
    private async Task ExecuteAsync<T>(Func<CancellationToken, Task<T>> operation, Action<T> publish, string progress)
    {
        if (!_active || _busy) return;
        _busy = true; int generation = ++_generation;
        using var cancel = new CancellationTokenSource(); _operation = cancel;
        CaptureStatusText.Text = progress; UpdateButtons();
        try
        {
            T result = await operation(cancel.Token);
            if (_active && generation == _generation && !cancel.IsCancellationRequested) publish(result);
            else if (_active && generation == _generation) CaptureStatusText.Text = "Operazione interrotta; eventuale file salvato può essere parziale.";
        }
        catch (OperationCanceledException) { if (_active && generation == _generation) CaptureStatusText.Text = "Operazione interrotta."; }
        catch (Exception ex)
        {
            if (_active && generation == _generation)
            { CaptureStatusText.Text = "Operazione non riuscita: " + ex.Message; if (_evidence is null) CaptureSummaryText.Text = "Risultato: N/D."; }
        }
        finally { _operation = null; _busy = false; UpdateButtons(); }
    }
    internal Task DiscoverAsync()
    {
        if (!_active || _busy) return Task.CompletedTask;
        _tools = null; _monitorVerified = false; CaptureInterfacesBox.ItemsSource = null;
        return ExecuteAsync(token => _client.DiscoverAsync(_selectedDumpcap, token), result =>
        {
            _tools = result.Tools; _monitorVerified = false;
            CaptureInterfacesBox.ItemsSource = result.Interfaces; CaptureInterfacesBox.SelectedIndex = -1;
            CaptureStatusText.Text = result.Detail;
            CaptureDetailsText.Text = _tools is null ? result.Detail : _tools.Dumpcap + "\n" + _tools.Tshark + "\n" + result.Detail;
        }, "Verifica strumenti e interfacce in corso…");
    }
    private async void Discover_Click(object sender, RoutedEventArgs e) => await DiscoverAsync();
    private async void ChooseTools_Click(object sender, RoutedEventArgs e)
    {
        var dialog = new OpenFileDialog { Title = "Scegli dumpcap.exe della tua installazione Wireshark", Filter = "Wireshark dumpcap|dumpcap.exe", CheckFileExists = true };
        if (dialog.ShowDialog() == true) { _selectedDumpcap = dialog.FileName; _tools = null; _monitorVerified = false; await DiscoverAsync(); }
    }
    private void Interface_Changed(object sender, SelectionChangedEventArgs e) { _monitorVerified = false; UpdateButtons(); }
    private void Monitor_Changed(object sender, RoutedEventArgs e) { _monitorVerified = false; UpdateButtons(); }
    internal Task VerifyMonitorAsync()
    {
        if (_tools is null || CaptureInterfacesBox.SelectedItem is not CaptureInterface adapter || CaptureMonitorBox.IsChecked != true) return Task.CompletedTask;
        if (!_active || _busy) return Task.CompletedTask;
        _monitorVerified = false;
        return ExecuteAsync(token => _client.CheckMonitorAsync(_tools, adapter, token), result =>
        { _monitorVerified = result.Supported; CaptureStatusText.Text = result.Detail; }, "Verifica monitor: la scheda può disconnettersi dal Wi-Fi…");
    }
    private async void Monitor_Click(object sender, RoutedEventArgs e) => await VerifyMonitorAsync();
    internal Task CaptureAsync(string path)
    {
        if (!_active || _busy || _tools is null || CaptureInterfacesBox.SelectedItem is not CaptureInterface adapter ||
            (CaptureMonitorBox.IsChecked == true && !_monitorVerified)) return Task.CompletedTask;
        bool monitor = CaptureMonitorBox.IsChecked == true;
        _evidence = null; CaptureObservationsTable.ItemsSource = null; CaptureSummaryText.Text = "Nessun campione analizzato per questa cattura.";
        _fileReady = false;
        _lastFile = path; CaptureFileText.Text = "File scelto: " + path;
        return ExecuteAsync(token => _client.CaptureAsync(_tools, adapter, monitor, path, token), result =>
        { _lastFile = _capturedFile = result.Path; _captureDetail = result.Detail; _fileReady = result.Complete; CaptureFileText.Text = result.Path; CaptureStatusText.Text = result.Detail; }, "Cattura in corso · massimo 20 secondi…");
    }
    private async void Capture_Click(object sender, RoutedEventArgs e)
    {
        var dialog = new SaveFileDialog { Title = "Salva in un nuovo file locale .pcapng", Filter = "Cattura pcapng|*.pcapng", FileName = "ProcessLens-" + DateTime.Now.ToString("yyyyMMdd-HHmmss") + ".pcapng", AddExtension = true, DefaultExt = ".pcapng" };
        if (dialog.ShowDialog() == true) await CaptureAsync(dialog.FileName);
    }
    internal Task AnalyzeAsync(string path)
    {
        if (!_active || _busy || _tools is null) return Task.CompletedTask;
        _evidence = null; CaptureObservationsTable.ItemsSource = null; CaptureSummaryText.Text = "Analisi in corso…";
        _fileReady = false;
        _lastFile = path; CaptureFileText.Text = "File selezionato: " + path;
        return ExecuteAsync(token => _client.AnalyzeAsync(_tools, path, token), result =>
        {
            _fileReady = true;
            _evidence = result with { Note = result.Note + (string.Equals(path, _capturedFile, StringComparison.OrdinalIgnoreCase) ? "\nEsito della cattura:\n" + _captureDetail : "") };
            CaptureObservationsTable.ItemsSource = result.Rows;
            CaptureSummaryText.Text = $"{result.Packets} pacchetti esaminati · {result.WifiFrames} frame 802.11" + (result.Limited ? " · campione limitato" : "");
            CaptureStatusText.Text = "Analisi del file completata."; CaptureDetailsText.Text = _evidence.Note;
        }, "Analisi locale con TShark in corso…");
    }
    private async void Read_Click(object sender, RoutedEventArgs e) { if (_lastFile is not null) await AnalyzeAsync(_lastFile); }
    private async void Import_Click(object sender, RoutedEventArgs e)
    {
        var dialog = new OpenFileDialog { Title = "Analizza una cattura locale · massimo 12 MiB", Filter = "Catture|*.pcapng;*.pcap", CheckFileExists = true };
        if (dialog.ShowDialog() == true) await AnalyzeAsync(dialog.FileName);
    }
    private void Stop_Click(object sender, RoutedEventArgs e) => _operation?.Cancel();
    private void UpdateButtons()
    {
        if (CopyCaptureButton is null) return;
        bool ready = _active && !_busy, selected = CaptureInterfacesBox.SelectedItem is CaptureInterface;
        DiscoverCaptureButton.IsEnabled = ChooseToolsButton.IsEnabled = ready;
        CaptureInterfacesBox.IsEnabled = CaptureMonitorBox.IsEnabled = ready;
        VerifyMonitorButton.IsEnabled = ready && _tools is not null && selected && CaptureMonitorBox.IsChecked == true;
        StartCaptureButton.IsEnabled = ready && _tools is not null && selected && (CaptureMonitorBox.IsChecked != true || _monitorVerified);
        StopCaptureButton.IsEnabled = _active && _busy;
        ImportCaptureButton.IsEnabled = ready && _tools is not null;
        ReadCaptureButton.IsEnabled = ready && _fileReady && _tools is not null && _lastFile is not null;
        OpenWiresharkButton.IsEnabled = ready && _fileReady && _tools is not null && _lastFile is not null;
        CopyCaptureButton.IsEnabled = ready && _evidence is not null;
    }
    private void Open_Click(object sender, RoutedEventArgs e)
    {
        if (_tools is null || _lastFile is null || !File.Exists(_lastFile) || !File.Exists(_tools.Wireshark)) return;
        try
        {
            var start = new ProcessStartInfo(_tools.Wireshark) { UseShellExecute = false };
            start.ArgumentList.Add("-r"); start.ArgumentList.Add(_lastFile);
            Process.Start(start)?.Dispose(); // Explicit user action opens a viewer, never a live capture.
        }
        catch (Exception ex) { CaptureStatusText.Text = "Apertura non riuscita: " + ex.Message; }
    }
    private void Copy_Click(object sender, RoutedEventArgs e)
    {
        if (_evidence is null) return;
        ClipboardText.Copy(this, "CATTURA WIRESHARK / WI-FI\n" + CaptureFileText.Text + "\n" + CaptureSummaryText.Text +
            "\n" + CaptureStatusText.Text + "\n\n" + GridCopySupport.CaptureTable(CaptureObservationsTable, false) + "\n\n" + _evidence.Note);
    }
}

private void NetworkTabs_Changed(object sender, SelectionChangedEventArgs e)
{
    if (NetworkTabs is null || NetworkCaptureHost is null || !ReferenceEquals(e.Source, NetworkTabs)) return;
    if (NetworkTabs.SelectedIndex == 1)
    {
        _generation++; _current = false; _snapshot = null; _view = null;
        _catalog = new(Array.Empty<DeviceRecognition>(), ""); NetworkDevicesTable.ItemsSource = null;
        NetworkIndicatorText.Text = "Elenco da aggiornare";
        NetworkSummaryText.Text = "Aggiorna la cache dopo le operazioni sulla scheda Wi-Fi.";
    }
    if (NetworkTabs.SelectedIndex == 1 && _captureView is null)
    {
        _captureView = new NetworkCaptureView();
        NetworkCaptureHost.Content = _captureView;
    }
    _captureView?.SetActive(_active && NetworkTabs.SelectedIndex == 1);
    UpdateButtons();
}

using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace ProcessLens.Core;

public sealed record CaptureInterface(string Name, string Description)
{
    public string Display => Description.Length > 0 ? Description + " · " + Name : Name;
}
public sealed record CaptureTools(string Dumpcap, string Tshark, string Wireshark, string DriverNote);
public sealed record CaptureDiscovery(CaptureTools? Tools, IReadOnlyList<CaptureInterface> Interfaces, string Detail);
public sealed record CaptureCheck(bool Supported, string Detail);
public sealed record CaptureFileResult(string Path, bool Complete, string Detail);
public sealed record PacketObservation(string Kind, string Mac, string Bssid, string Ssid,
    string Frequency, string Signal, int Frames);
public sealed record PacketEvidence(int Packets, int WifiFrames, bool Limited,
    IReadOnlyList<PacketObservation> Rows, string Note);
public interface IPacketCaptureClient
{
    Task<CaptureDiscovery> DiscoverAsync(string? dumpcapPath, CancellationToken token);
    Task<CaptureCheck> CheckMonitorAsync(CaptureTools tools, CaptureInterface adapter, CancellationToken token);
    Task<CaptureFileResult> CaptureAsync(CaptureTools tools, CaptureInterface adapter, bool monitor, string output, CancellationToken token);
    Task<PacketEvidence> AnalyzeAsync(CaptureTools tools, string path, CancellationToken token);
}

public static class PacketCapturePolicy
{
    public const int Seconds = 20, FileKilobytes = 10000, Packets = 10000, Snaplen = 256, AnalysisPackets = 2048;
    public const int MaximumFileBytes = 12 * 1024 * 1024, MaximumTextChars = 512 * 1024;
    public static bool LocalInterface(string name) => name == @"\Device\NPF_Loopback" ||
        (name.StartsWith(@"\Device\NPF_", StringComparison.Ordinal) && name.Length == 50 &&
         Guid.TryParseExact(name[12..], "B", out _));
    public static string[] CaptureArguments(CaptureInterface adapter, bool monitor, string path)
    {
        if (!LocalInterface(adapter.Name)) throw new ArgumentException("Interfaccia locale Npcap non valida.");
        if (!Path.IsPathFullyQualified(path) || path.StartsWith(@"\\", StringComparison.Ordinal) || !path.EndsWith(".pcapng", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("Scegli un nuovo file locale .pcapng.");
        var args = new List<string> { "-i", adapter.Name };
        if (monitor) args.Add("-I"); else args.Add("-p");
        args.AddRange(new[] { "-a", "duration:20", "-a", "filesize:10000", "-c", "10000", "-s", "256", "-B", "2", "-q", "-w", path });
        return args.ToArray();
    }
    public static string[] AnalysisArguments(string path)
    {
        var args = new List<string> { "-n", "-r", path, "-c", "2048", "-T", "fields", "-E", "separator=/t", "-E", "quote=n", "-E", "occurrence=f", "-E", "escape=y" };
        foreach (string field in new[] { "frame.number", "wlan.ta", "wlan.ra", "wlan.bssid", "wlan.fc.type", "wlan.fc.subtype", "wlan.ssid", "radiotap.channel.freq", "radiotap.dbm_antsignal" })
            args.AddRange(new[] { "-e", field });
        return args.ToArray();
    }
    public static IReadOnlyList<CaptureInterface> ParseInterfaces(string text) => text.Split('\n').Take(512)
        .Select(line => Regex.Match(line.TrimEnd('\r'), @"^\d+\. (?<name>\S+)(?: \((?<description>.*)\))?$", RegexOptions.CultureInvariant))
        .Where(m => m.Success && LocalInterface(m.Groups["name"].Value))
        .Select(m => new CaptureInterface(m.Groups["name"].Value, m.Groups["description"].Value))
        .DistinctBy(x => x.Name).ToArray();
    public static bool HasMonitorLinkType(string text) => Regex.IsMatch(text, @"(?m)^\s*IEEE802_11(?:_RADIO)?(?:\s|\(|$)", RegexOptions.CultureInvariant);
}

public static class PacketEvidenceParser
{
    private static int? Number(string value)
    {
        if (value.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
            return int.TryParse(value.AsSpan(2), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out int hex) ? hex : null;
        return int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int number) ? number : null;
    }
    private static string Ssid(string raw)
    {
        if (raw.Length == 0) return "N/D";
        string hex = raw.Replace(":", "", StringComparison.Ordinal);
        if (hex.Length > 64 || hex.Length % 2 != 0 || hex.Any(c => !Uri.IsHexDigit(c))) return "SSID non decodificato";
        try
        {
            string value = new UTF8Encoding(false, true).GetString(Convert.FromHexString(hex));
            return string.Concat(value.Select(c => char.IsControl(c) || char.GetUnicodeCategory(c) == UnicodeCategory.Format ? "\\u" + ((int)c).ToString("X4") : c.ToString()));
        }
        catch (DecoderFallbackException) { return "SSID hex: " + hex; }
    }
    public static PacketEvidence Parse(string text)
    {
        bool limited = text.Length > PacketCapturePolicy.MaximumTextChars;
        if (limited) text = text[..PacketCapturePolicy.MaximumTextChars];
        int packets = 0, wifi = 0;
        var rows = new Dictionary<(string Kind, string Mac, string Bssid, string Ssid, string Frequency, string Signal), int>();
        foreach (string line in text.Split('\n'))
        {
            if (line.Length == 0) continue;
            if (packets == PacketCapturePolicy.AnalysisPackets) { limited = true; break; }
            string[] f = line.TrimEnd('\r').Split('\t');
            if (f.Length != 9 || f.Any(v => v.Length > 512) || Number(f[0]) is not > 0) { limited = true; continue; }
            packets++;
            int? type = Number(f[4]), subtype = Number(f[5]);
            if (type is not (>= 0 and <= 3)) { if (f[4].Length > 0) limited = true; continue; }
            wifi++;
            string bssid = NetworkDeviceRules.NormalizeMac(f[3]);
            string ssid = type == 0 && subtype is 5 or 8 ? Ssid(f[6]) : "N/D";
            string frequency = Number(f[7]) is > 0 and < 100000 ? f[7] + " MHz" : "N/D";
            string signal = Number(f[8]) is >= -200 and <= 0 ? f[8] + " dBm" : "N/D";
            void Add(string kind, string mac)
            {
                mac = NetworkDeviceRules.NormalizeMac(mac);
                if (mac.Length == 0) return;
                var key = (kind, mac, bssid.Length > 0 ? bssid : "N/D", ssid, frequency, signal);
                if (rows.TryGetValue(key, out int count)) rows[key] = count + 1;
                else if (rows.Count < 512) rows[key] = 1;
                else limited = true;
            }
            Add("Trasmettitore nel frame", f[1]);
            Add("Destinatario nel frame", f[2]);
            Add(type == 0 && subtype is 5 or 8 ? "Rete annunciata" : "BSSID nel frame", f[3]);
        }
        if (packets == PacketCapturePolicy.AnalysisPackets) limited = true;
        var observations = rows.Select(r => new PacketObservation(r.Key.Kind, r.Key.Mac, r.Key.Bssid, r.Key.Ssid, r.Key.Frequency, r.Key.Signal, r.Value)).ToArray();
        return new(packets, wifi, limited, observations,
            "Campione iniziale del file: massimo 2.048 pacchetti. Indirizzi e SSID sono dichiarati nei frame; non verificano identità, associazione attuale o origine da un telefono/hotspot. " +
            (wifi == 0 ? "Nessun frame 802.11 decodificato nel campione: una cattura normale può avere solo intestazioni Ethernet." :
                "Osservati frame 802.11 nel file; la ricezione non copre tutti i canali o tutti i dispositivi."));
    }
}

using System.ComponentModel;
using System.Diagnostics;
using System.Text;
using System.Security.Cryptography;
using ProcessLens.Core;

namespace ProcessLens.Windows;

public sealed record CaptureCommandResult(int ExitCode, string Output, string Error, bool Interrupted)
{
    public bool Success => ExitCode == 0 && !Interrupted;
}
public interface ICaptureCommandRunner
{
    Task<CaptureCommandResult> RunAsync(string executable, IReadOnlyList<string> arguments, int seconds, CancellationToken token);
}

public sealed class CaptureCommandRunner : ICaptureCommandRunner
{
    public async Task<CaptureCommandResult> RunAsync(string executable, IReadOnlyList<string> arguments, int seconds, CancellationToken token)
    {
        token.ThrowIfCancellationRequested();
        using var child = new Process { StartInfo = new ProcessStartInfo(executable) {
            UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true,
            StandardOutputEncoding = Encoding.UTF8, StandardErrorEncoding = Encoding.UTF8,
            WorkingDirectory = Path.GetDirectoryName(executable)!
        }};
        foreach (string argument in arguments) child.StartInfo.ArgumentList.Add(argument);
        using var budget = CancellationTokenSource.CreateLinkedTokenSource(token);
        budget.CancelAfter(TimeSpan.FromSeconds(seconds));
        var output = new StringBuilder(); var error = new StringBuilder();
        bool started = false, interrupted = false; int overflow = 0;
        async Task ReadAsync(StreamReader reader, StringBuilder destination)
        {
            char[] buffer = new char[4096];
            try
            {
                int count;
                while ((count = await reader.ReadAsync(buffer.AsMemory(), budget.Token)) > 0)
                {
                    int remaining = PacketCapturePolicy.MaximumTextChars - destination.Length;
                    destination.Append(buffer, 0, Math.Min(remaining, count));
                    if (count > remaining) { Interlocked.Exchange(ref overflow, 1); budget.Cancel(); break; }
                }
            }
            catch (OperationCanceledException) { }
            catch (IOException) when (budget.IsCancellationRequested) { }
        }
        try
        {
            if (!child.Start()) return new(-1, "", "Avvio dello strumento non riuscito.", false);
            started = true;
            Task stdout = ReadAsync(child.StandardOutput, output), stderr = ReadAsync(child.StandardError, error);
            try { await child.WaitForExitAsync(budget.Token); }
            catch (OperationCanceledException)
            {
                interrupted = true;
                if (!child.HasExited) child.Kill(); // Only the exact child started above, never a process-name lookup.
                using var stop = new CancellationTokenSource(TimeSpan.FromSeconds(3));
                await child.WaitForExitAsync(stop.Token);
            }
            await Task.WhenAll(stdout, stderr);
            string reason = token.IsCancellationRequested ? "Operazione interrotta." : overflow != 0 ? "Output oltre il limite." : interrupted ? "Tempo massimo superato." : "";
            return new(child.ExitCode, output.ToString(), reason + (reason.Length > 0 ? "\n" : "") + error, interrupted || overflow != 0);
        }
        catch (Exception ex) when (ex is IOException or Win32Exception or InvalidOperationException or OperationCanceledException)
        { return new(-1, "", "Strumento non disponibile: " + ex.Message, true); }
        finally
        {
            budget.Cancel();
            if (started)
                try { if (!child.HasExited) child.Kill(); }
                catch (InvalidOperationException) { }
                catch (Win32Exception) { }
        }
    }
}

public sealed class WiresharkTools : IPacketCaptureClient
{
    private readonly ICaptureCommandRunner _runner;
    private readonly HashSet<string> _verifiedMonitor = new(StringComparer.Ordinal);
    public WiresharkTools(ICaptureCommandRunner? runner = null) => _runner = runner ?? new CaptureCommandRunner();
    private static string Stamp(CaptureTools tools, CaptureInterface adapter)
    {
        var file = new FileInfo(tools.Dumpcap);
        return tools.Dumpcap + "|" + file.Length + "|" + file.LastWriteTimeUtc.Ticks + "|" + adapter.Name;
    }
    private static void ValidateTools(CaptureTools tools)
    {
        foreach (var (path, name) in new[] { (tools.Dumpcap, "dumpcap.exe"), (tools.Tshark, "tshark.exe") })
            if (!Path.IsPathFullyQualified(path) || path.StartsWith(@"\\", StringComparison.Ordinal) || !File.Exists(path) ||
                !Path.GetFileName(path).Equals(name, StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(Path.GetDirectoryName(path), Path.GetDirectoryName(tools.Dumpcap), StringComparison.OrdinalIgnoreCase))
                throw new IOException("Seleziona dumpcap.exe nella cartella di installazione di Wireshark, con tshark.exe accanto.");
    }
    public async Task<CaptureDiscovery> DiscoverAsync(string? dumpcapPath, CancellationToken token)
    {
        _verifiedMonitor.Clear();
        if (dumpcapPath is null)
        {
            dumpcapPath = new[] { Environment.SpecialFolder.ProgramFiles, Environment.SpecialFolder.ProgramFilesX86 }
                .Select(f => Path.Combine(Environment.GetFolderPath(f), "Wireshark", "dumpcap.exe"))
                .FirstOrDefault(File.Exists);
        }
        if (dumpcapPath is null) return new(null, Array.Empty<CaptureInterface>(), "Wireshark non rilevato. Installa Wireshark con TShark e Npcap, poi scegli Verifica strumenti.");
        string directory = Path.GetDirectoryName(Path.GetFullPath(dumpcapPath))!;
        string npcap = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System), "Npcap", "wpcap.dll");
        var tools = new CaptureTools(Path.GetFullPath(dumpcapPath), Path.Combine(directory, "tshark.exe"), Path.Combine(directory, "Wireshark.exe"),
            File.Exists(npcap) ? "File Npcap rilevati; il supporto monitor va verificato per scheda e driver." : "File Npcap non rilevati nel percorso standard: verifica l’installazione.");
        ValidateTools(tools);
        var result = await _runner.RunAsync(tools.Dumpcap, new[] { "-D" }, 10, token);
        return new(tools, result.Success ? PacketCapturePolicy.ParseInterfaces(result.Output) : Array.Empty<CaptureInterface>(),
            tools.DriverNote + "\n" + (result.Success ? "Elenco interfacce locali aggiornato." : "Elenco interfacce non disponibile: " + result.Error));
    }
    public async Task<CaptureCheck> CheckMonitorAsync(CaptureTools tools, CaptureInterface adapter, CancellationToken token)
    {
        ValidateTools(tools);
        if (!PacketCapturePolicy.LocalInterface(adapter.Name)) throw new ArgumentException("Interfaccia locale non valida.");
        string stamp = Stamp(tools, adapter); _verifiedMonitor.Remove(stamp);
        var result = await _runner.RunAsync(tools.Dumpcap, new[] { "-i", adapter.Name, "-I", "-L" }, 10, token);
        bool supported = result.Success && PacketCapturePolicy.HasMonitorLinkType(result.Output);
        if (supported) _verifiedMonitor.Add(stamp);
        return new(supported, supported ? "Lo strumento dichiara intestazioni 802.11 in modalità monitor. La ricezione va verificata con una cattura." :
            "Modalità monitor non verificata. Controlla driver, Npcap e permessi.\n" + result.Error + "\n" + result.Output);
    }
    public async Task<CaptureFileResult> CaptureAsync(CaptureTools tools, CaptureInterface adapter, bool monitor, string output, CancellationToken token)
    {
        ValidateTools(tools); token.ThrowIfCancellationRequested();
        if (monitor && !_verifiedMonitor.Contains(Stamp(tools, adapter)))
            throw new InvalidOperationException("Verifica la modalità monitor per questa interfaccia prima di acquisire.");
        string[] args = PacketCapturePolicy.CaptureArguments(adapter, monitor, output);
        // Reserve a NEW user-selected file; never overwrite an existing recording.
        using (File.Open(output, FileMode.CreateNew, FileAccess.Write, FileShare.None)) { }
        var result = await _runner.RunAsync(tools.Dumpcap, args, PacketCapturePolicy.Seconds + 10, token);
        long bytes = new FileInfo(output).Length;
        bool complete = result.Success && bytes > 0 && bytes <= PacketCapturePolicy.MaximumFileBytes;
        return new(output, complete, complete ? "Cattura terminata entro i limiti impostati.\n" + result.Error :
            "Cattura interrotta, non valida o parziale. Il file può essere incompleto.\n" + result.Error);
    }
    public async Task<PacketEvidence> AnalyzeAsync(CaptureTools tools, string path, CancellationToken token)
    {
        ValidateTools(tools);
        if (!Path.IsPathFullyQualified(path) || path.StartsWith(@"\\", StringComparison.Ordinal)) throw new IOException("Scegli un file locale.");
        await using var file = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 65536, useAsync: true);
        if (file.Length == 0 || file.Length > PacketCapturePolicy.MaximumFileBytes)
            throw new IOException("File mancante, vuoto o oltre il limite di 12 MiB.");
        string hash = Convert.ToHexString(await SHA256.HashDataAsync(file, token));
        var result = await _runner.RunAsync(tools.Tshark, PacketCapturePolicy.AnalysisArguments(path), 15, token);
        if (!result.Success) throw new IOException("Analisi non disponibile o interrotta: " + result.Error);
        var evidence = PacketEvidenceParser.Parse(result.Output);
        return evidence with { Note = evidence.Note + "\nSHA-256 del file letto: " + hash };
    }
}
